parameters.jsCode:
// 解析监控API返回结果
const monitoring = $input.item.json;

// 提取时间状态
const timeStatus = monitoring.timeStatus;
const currentTime = monitoring.currentTime;

// 提取数据源状态
const sources = monitoring.dataSources;
const alerts = monitoring.alerts || [];
const summary = monitoring.summary;

// 构建可读的报告
const report = {
  timestamp: monitoring.timestamp,
  currentTime: currentTime,
  timeStatus: {
    emoji: timeStatus.emoji,
    state: timeStatus.state,
    description: timeStatus.description
  },
  dataSources: {
    etf: {
      name: sources.etf_daily.name,
      total: sources.etf_daily.total,
      ok: sources.etf_daily.ok,
      delayed: sources.etf_daily.delayed,
      failed: sources.etf_daily.failed,
      status: sources.etf_daily.failed > 0 ? '❌失败' : (sources.etf_daily.delayed > 0 ? '⚠️延迟' : '✅正常')
    },
    index: {
      name: sources.index_daily.name,
      total: sources.index_daily.total,
      ok: sources.index_daily.ok,
      delayed: sources.index_daily.delayed,
      failed: sources.index_daily.failed,
      status: sources.index_daily.failed > 0 ? '❌失败' : (sources.index_daily.delayed > 0 ? '⚠️延迟' : '✅正常')
    },
    minute: {
      name: sources.minute.name,
      status: sources.minute.status,
      message: sources.minute.message,
      lastUpdate: sources.minute.last_update || null,
      statusEmoji: sources.minute.status === 'ok' ? '✅' : (sources.minute.status === 'stale' ? '⚠️' : '❌')
    },
    market: {
      name: sources.market_snapshot.name,
      status: sources.market_snapshot.status,
      lastUpdate: sources.market_snapshot.last_update,
      minutesAgo: sources.market_snapshot.minutes_ago || 0,
      statusEmoji: sources.market_snapshot.status === 'ok' ? '✅' : (sources.market_snapshot.status === 'stale' ? '⚠️' : '❌')
    },
    warmup: {
      name: sources.warmup.name,
      status: sources.warmup.status,
      latestDate: sources.warmup.latest_date,
      statusEmoji: sources.warmup.status === 'ok' ? '✅' : (sources.warmup.status === 'delayed' ? '⚠️' : '❌')
    },
    lifecycle: {
      name: sources.lifecycle.name,
      status: sources.lifecycle.status,
      latestDate: sources.lifecycle.latest_date,
      statusEmoji: sources.lifecycle.status === 'ok' ? '✅' : (sources.lifecycle.status === 'delayed' ? '⚠️' : '❌')
    }
  },
  summary: {
    totalSources: summary.total_sources,
    healthy: summary.healthy_sources,
    warnings: summary.warning_sources,
    errors: summary.error_sources
  },
  alerts: alerts.map(a => ({
    level: a.level === 'error' ? '❌' : '⚠️',
    source: a.source,
    message: a.message
  }))
};

return report;

